/**
 * Run the forms rendering browser test.
 *
 *   node tests/forms-render-browser-test.js
 *
 * The page under test is generated by `tests/forms-render-browser-fixture.php`
 * from the real renderer, and links the plugin's real stylesheet and real
 * provisioning script. This runner finds a browser, drives the page twice —
 * once where provisioning succeeds and once where it fails — and reads the
 * results back out of the document title.
 *
 * A missing browser is a skip, not a pass. Set AGENTSHELL_REQUIRE_BROWSER=1 to
 * turn the skip into a failure — which is what CI does, because a skip is not a
 * test.
 *
 * Set AGENTSHELL_PHP to choose the PHP binary (default: `php`).
 */

'use strict';

var child_process = require( 'child_process' );
var fs = require( 'fs' );
var os = require( 'os' );
var path = require( 'path' );

var CANDIDATES = [
    process.env.AGENTSHELL_BROWSER,
    'google-chrome',
    'google-chrome-stable',
    'chromium',
    'chromium-browser',
    'chrome',
];

function find_browser() {
    for ( var i = 0; i < CANDIDATES.length; i++ ) {
        var name = CANDIDATES[ i ];
        if ( ! name ) { continue; }
        try {
            var found = child_process.execFileSync( 'which', [ name ], { stdio: [ 'ignore', 'pipe', 'ignore' ] } );
            var path_found = found.toString().trim();
            if ( path_found ) { return path_found; }
        } catch ( e ) {
            // Not on PATH: try the next one.
        }
    }
    return null;
}

function php_binary() {
    return process.env.AGENTSHELL_PHP || 'php';
}

function generate_page( out_file ) {
    var fixture = path.join( __dirname, 'forms-render-browser-fixture.php' );

    if ( ! fs.existsSync( fixture ) ) {
        throw new Error( 'the fixture generator is missing: ' + fixture );
    }

    var output = child_process.execFileSync( php_binary(), [ fixture, out_file ], {
        stdio: [ 'ignore', 'pipe', 'pipe' ],
        maxBuffer: 16 * 1024 * 1024,
        // A generator that never returns is a failure, not a hang: without a
        // bound, a broken PHP or a stuck fixture would hold the whole suite
        // until the CI job's own timeout, and the report would say nothing.
        timeout: 60000,
    } ).toString();

    if ( ! fs.existsSync( out_file ) ) {
        throw new Error( 'the fixture was not written: ' + output );
    }
}

function run_scenario( browser, page, profile, scenario ) {
    var args = [
        '--headless',
        '--disable-gpu',
        '--no-sandbox',
        '--disable-dev-shm-usage',
        '--force-prefers-reduced-motion',
        '--user-data-dir=' + profile,
        '--virtual-time-budget=20000',
        '--window-size=1280,900',
        '--dump-dom',
        'file://' + page + ( scenario ? '?scenario=' + scenario : '' ),
    ];

    var output = '';
    var failed_to_run = null;

    try {
        output = child_process.execFileSync( browser, args, {
            maxBuffer: 64 * 1024 * 1024,
            stdio: [ 'ignore', 'pipe', 'pipe' ],
            // A browser that starts and never finishes is a failure. The bound
            // is generous — the page's own virtual time budget is 20s — and it
            // exists so a stuck browser reports rather than hangs.
            timeout: 180000,
        } ).toString();
    } catch ( e ) {
        failed_to_run = e;
        output = ( e.stdout ? e.stdout.toString() : '' );
    }

    if ( failed_to_run && ! output ) {
        throw new Error( 'the browser did not run: ' + ( failed_to_run.message || failed_to_run ) );
    }

    var match = output.match( /<title>([\s\S]*?)<\/title>/ );
    if ( ! match ) {
        throw new Error( 'the harness did not report a result' );
    }

    var title = match[ 1 ]
        .replace( /&quot;/g, '"' )
        .replace( /&#39;/g, "'" )
        .replace( /&lt;/g, '<' )
        .replace( /&gt;/g, '>' )
        .replace( /&amp;/g, '&' );

    var report;
    try {
        report = JSON.parse( title );
    } catch ( e ) {
        throw new Error( 'the harness reported something that is not JSON: ' + title.slice( 0, 400 ) );
    }

    if ( report.harness_error ) {
        throw new Error( 'the harness itself failed: ' + report.harness_error );
    }

    return report;
}

function main() {
    var browser = find_browser();

    if ( ! browser ) {
        var message = 'no browser found (looked for ' + CANDIDATES.filter( Boolean ).join( ', ' ) + ')';
        if ( process.env.AGENTSHELL_REQUIRE_BROWSER === '1' ) {
            console.error( 'FAIL the forms browser test needs a browser: ' + message );
            process.exit( 1 );
        }
        console.log( 'SKIP: ' + message );
        process.exit( 0 );
    }

    var work = fs.mkdtempSync( path.join( os.tmpdir(), 'agentshell-forms-browser-' ) );
    var page = path.join( work, 'fixture.html' );
    var profile = path.join( work, 'profile' );

    var scenarios = [];
    var failures = [];

    try {
        try {
            generate_page( page );
        } catch ( e ) {
            console.error( 'FAIL the page could not be generated: ' + ( e.message || e ) );
            process.exit( 1 );
        }

        fs.mkdirSync( profile, { recursive: true } );

        // The happy path, then the failure path: a form that could not be
        // prepared must say so rather than sit there looking ready.
        [ [ 'ok', '' ], [ 'fail', 'fail' ] ].forEach( function ( pair ) {
            var name = pair[ 0 ];
            var scenario = pair[ 1 ];

            var report;
            try {
                report = run_scenario( browser, page, profile, scenario );
            } catch ( e ) {
                failures.push( { name: name + ': the browser reported', detail: ( e.message || String( e ) ).slice( 0, 500 ) } );
                return;
            }

            scenarios.push( report );
            ( report.failures || [] ).forEach( function ( failure ) {
                failures.push( { name: name + ': ' + failure.name, detail: failure.detail } );
            } );

            if ( report.errors && report.errors.length ) {
                failures.push( { name: name + ': page errors', detail: report.errors.join( '; ' ) } );
            }
        } );
    } finally {
        try { fs.rmSync( work, { recursive: true, force: true } ); } catch ( e ) {
            // A profile the browser still holds open is not a test failure.
        }
    }

    var total = scenarios.reduce( function ( sum, report ) { return sum + ( report.total || 0 ); }, 0 );

    failures.forEach( function ( failure ) {
        console.log( '  FAIL ' + failure.name + ( failure.detail === null || failure.detail === undefined ? '' : ' (' + failure.detail + ')' ) );
    } );

    var passed = total - failures.length;

    console.log( '  the page ran ' + total + ' browser assertions against the real renderer, stylesheet and script' );
    console.log( '\n' + passed + ' passed, ' + failures.length + ' failed' );

    if ( failures.length > 0 ) {
        process.exit( 1 );
    }
}

main();
